contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public {
        // deployer (this contract) received the whole initial supply in the constructor
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(amount > supplyBefore); // sender's balance equals total supply initially
        address recipient = address(0xBEEF);
        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipBefore = c.balanceOf(recipient); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transfer(recipient, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.balanceOf(address(this)) == senderBefore && c.balanceOf(recipient) == recipBefore && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}

