pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 amount) internal {
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        vm.assume(amount > supplyBefore);
        address recipient = address(0xBEEF);
        uint256 senderBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { senderBefore = __r; } catch { return; }
        uint256 recipBefore;
        try c.balanceOf(recipient) returns (uint256 __r) { recipBefore = __r; } catch { return; }
        bool reverted;
        try c.transfer(recipient, amount) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && c.balanceOf(address(this)) == senderBefore && c.balanceOf(recipient) == recipBefore && c.totalSupply() == supplyBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
